pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes == "ping" {
        return Ok(Msg::Ping);
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let message = Msg::Hello("client".into());
        let encoded = encode(&message);
        assert_eq!(encoded, "v:2|hello:client");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "client"));
    }

    #[test]
    fn unversioned_hello_is_unknown() {
        assert!(decode("hello:client").is_err());
    }
}

